from collections import deque
import json,os

def components(g,color):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==color and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx]==color and (ny,nx) not in seen:
                                seen.add((ny,nx)); q.append((ny,nx))
                out.append(comp)
    return out

def transform(g):
    h,w=len(g),len(g[0])
    bg=max(set(v for r in g for v in r), key=lambda c: sum(r.count(c) for r in g))
    out=[[bg]*w for _ in range(h)]
    for c in set(v for r in g for v in r)-{bg}:
        for comp in components(g,c):
            if len(comp)>=5:
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                for y in range(min(ys),max(ys)+1):
                    for x in range(min(xs),max(xs)+1):
                        out[y][x]=c
    return out

